import sys
import os
import traceback

def make_unraisablehook(old_hook):
    def hook(exc, value, traceback):
        current_test = os.environ.get("PYTEST_CURRENT_TEST")
        if current_test:
            print(f"Unraisable exception in test {current_test}:", file=sys.stderr)

        if old_hook is not None:
            old_hook(exc, value, traceback)
        else:
            # Default behavior: print the exception
            try:
                print(f"Unraisable exception: {value}", file=sys.stderr)
            except Exception:
                print(f"Unraisable exception of type {type(value).__name__}", file=sys.stderr)
            traceback.print_tb(traceback, file=sys.stderr)
    return hook

