            if t.is_even:
                min_ord2 += 1
                max_ord2 = float('inf')
            elif t.is_odd:
                min_ord2 += 0
                max_ord2 += 0
            else:
                return None
        elif t.is_Rational:
            n, d = t.as_numer_denom()
            def get_ord2(x):
                if x == 0:
                    return float('inf')
                return (x & -x).bit_length() - 1 if x != 0 else float('inf')
            n_ord = get_ord2(abs(n))
            d_ord = get_ord2(abs(d))
            min_ord2 += n_ord - d_ord
            max_ord2 += n_ord - d_ord
        elif t.is_Pow:
